import React, {useEffect, useState} from "react";
import {Alert, Box, Button, Checkbox, Chip, Dialog, DialogActions, DialogContent, DialogContentText, DialogTitle, LinearProgress, MenuItem, Stack, Table, TableBody, TableCell, TableContainer, TableHead, TableRow, TextField, Typography} from "@mui/material";
import UploadFileOutlinedIcon from "@mui/icons-material/UploadFileOutlined";
import PhotoCameraOutlinedIcon from "@mui/icons-material/PhotoCameraOutlined";
import {Link as RouterLink, useSearchParams} from "react-router-dom";
import {MainDiv, PageHeader, PageTitle, PageTitleGroup, PageSubtitle, Surface} from "../../../ui/commonStyled/commonStyled";
import {useTranslation} from "../../../i18n";
import {CategoryType} from "../../../models/category";
import {useGetLastLevelCategoriesQuery} from "../../categories/categoriesApi";
import {useApproveRecognitionDraftsMutation, useClearRecognitionBufferMutation, useDeleteRecognitionDraftMutation, useGetRecognitionBatchQuery, useGetRecognitionBatchesQuery, useGetRecognitionCapabilitiesQuery, useGetRecognitionDraftQuery, useRecognizeProductsMutation} from "../../products/productsApi";
import {ApproveProductDraftsResult, ProductRecognitionDraft} from "../../../models/productRecognition";
import {getApiErrorMessage} from "../../../api/errors";
import QueryError from "../../shared/QueryError";
import CatalogGenerationTabs from "../CatalogGenerationTabs";
import ProductDraftEditor from "./ProductDraftEditor";
import ProductLifecycleLink from "../lifecycle/ProductLifecycleLink";

export default function ProductRecognitionPage() {
    const {t} = useTranslation();
    const [search, setSearch] = useSearchParams();
    const batchId = search.get("batch") || "";
    const [files, setFiles] = useState<File[]>([]);
    const [dragging, setDragging] = useState(false);
    const [categoryId, setCategoryId] = useState("");
    const [error, setError] = useState("");
    const [progress, setProgress] = useState("");
    const [uploading, setUploading] = useState(false);
    const [draftId, setDraftId] = useState("");
    const [clearOpen, setClearOpen] = useState(false);
    const [clearError, setClearError] = useState("");
    const [deleteTarget, setDeleteTarget] = useState<ProductRecognitionDraft | null>(null);
    const [deleteError, setDeleteError] = useState("");
    const [removingBatchId, setRemovingBatchId] = useState("");
    const [selectedIds, setSelectedIds] = useState<string[]>([]);
    const [approvalResult, setApprovalResult] = useState<(ApproveProductDraftsResult & {batchId: string}) | null>(null);
    const [clearBuffer, clearing] = useClearRecognitionBufferMutation();
    const [deleteDraft, deleting] = useDeleteRecognitionDraftMutation();
    const capabilities = useGetRecognitionCapabilitiesQuery();
    const batches = useGetRecognitionBatchesQuery();
    // Unsubscribe during deletion so cache invalidation cannot reload deleted records.
    const removingBatch = !!batchId && batchId === removingBatchId;
    const batch = useGetRecognitionBatchQuery(batchId, {skip: !batchId || removingBatch || clearing.isLoading});
    const draft = useGetRecognitionDraftQuery(draftId, {skip: !draftId || removingBatch || clearing.isLoading || deleting.isLoading});
    const categories = useGetLastLevelCategoriesQuery({type: CategoryType.Product});
    const [recognize] = useRecognizeProductsMutation();
    const [approveMany, approvingMany] = useApproveRecognitionDraftsMutation();
    const activeBatch = batch.currentData;
    const bufferBusy = uploading || clearing.isLoading || approvingMany.isLoading || deleting.isLoading;
    const importBusy = uploading || clearing.isLoading || approvingMany.isLoading || deleting.isLoading;
    const eligible = activeBatch?.drafts.filter(item => item.status === "Pending" && item.card.name.trim()) ?? [];
    const selected = eligible.filter(item => selectedIds.includes(item.id));
    useEffect(() => {setSelectedIds([]); setApprovalResult(null);}, [batchId]);
    const hasAi = capabilities.data?.aiAvailable === true;
    const needsAi = files.some(file => /\.(pdf|png|jpe?g|webp)$/i.test(file.name));
    const aiRequired = needsAi && !hasAi;

    const selectFiles = (selected: File[]) => {
        setDragging(false);
        setError("");
        if (selected.some(file => !/\.(xlsx?|csv|pdf|png|jpe?g|webp)$/i.test(file.name))) {
            setError(t("Поддерживаются Excel, CSV, PDF и изображения PNG, JPG, WEBP.")); return;
        }
        if (selected.some(file => file.size === 0 || file.size > 10 * 1024 * 1024)) {
            setError(t("Выберите непустые файлы размером до 10 МБ каждый.")); return;
        }
        setFiles(selected);
    };

    const upload = async () => {
        setError("");
        if (!files.length || aiRequired) return;
        if (!categoryId) {setError(t("Перед распознаванием выберите категорию товаров.")); return;}
        if (files.some(file => file.size === 0 || file.size > 10 * 1024 * 1024)) {setError(t("Выберите непустые файлы размером до 10 МБ каждый.")); return;}
        setUploading(true);
        const remaining = [...files];
        try {
            for (const file of files) {
                setProgress(file.name);
                const body = new FormData();
                body.append("file", file);
                body.append("headerRow", "1");
                body.append("useAi", "true");
                body.append("categoryId", categoryId);
                const result = await recognize(body).unwrap();
                remaining.shift();
                setSearch({batch: result.id});
            }
        } catch (failure) {setError(getApiErrorMessage(failure, t("Не удалось распознать файл.")));}
        finally {setFiles(remaining); setUploading(false); setProgress("");}
    };

    const approveSelected = async () => {
        if (!selected.length) return;
        setError("");
        setApprovalResult(null);
        try {
            const result = await approveMany({batchId, drafts: selected.map(item => ({id: item.id, version: item.version}))}).unwrap();
            setSelectedIds(result.failed.map(item => item.id));
            setApprovalResult({...result, batchId});
        } catch (failure) {setError(getApiErrorMessage(failure, t("Не удалось добавить выбранные карточки в каталог.")));}
    };
    const clear = async () => {
        if (!clearOpen) return;
        setClearError("");
        setRemovingBatchId(batchId);
        try {
            await clearBuffer(undefined).unwrap();
            setDraftId("");
            setSearch(current => {const next = new URLSearchParams(current); next.delete("batch"); return next;});
            setClearOpen(false);
        } catch (failure) {
            setRemovingBatchId("");
            setClearError(getApiErrorMessage(failure, t("Не удалось очистить буфер.")));
        }
    };
    const removeCard = async () => {
        if (!deleteTarget) return;
        setDeleteError("");
        try {
            await deleteDraft({id: deleteTarget.id, version: deleteTarget.version}).unwrap();
            setSelectedIds(current => current.filter(id => id !== deleteTarget.id));
            setApprovalResult(null);
            if (draftId === deleteTarget.id) setDraftId("");
            setDeleteTarget(null);
        } catch (failure) {setDeleteError(getApiErrorMessage(failure, t("Не удалось удалить карточку.")));}
    };
    const statusLabel = {Pending: t("На одобрении"), Approved: t("В каталоге"), Rejected: t("Отклонён")};

    return <MainDiv>
        <CatalogGenerationTabs/>
        <ProductLifecycleLink step={3}/>
        <PageHeader><PageTitleGroup><PageTitle>{t("Генерация из файла контрагента")}</PageTitle><PageSubtitle>{t("Загрузите таблицу, PDF, скан или фото рукописного списка товаров. Проверьте карточки перед добавлением в каталог.")}</PageSubtitle></PageTitleGroup></PageHeader>
        <Stack spacing={3}>
            <Surface><Stack spacing={2}>
                {capabilities.isError && <QueryError error={capabilities.error} onRetry={capabilities.refetch}/>}
                {capabilities.data && !hasAi && <Alert severity="info">{t("ИИ не подключён. Можно подготовить карточки из колонок Excel/CSV и заполнить их вручную.")}</Alert>}
                <Stack direction="row" gap={1} flexWrap="wrap">{["Excel / CSV", "PDF", "Фото и сканы", "Рукописные списки"].map(format => <Chip key={format} size="small" variant="outlined" label={t(format)}/>)}</Stack>
                <TextField select required SelectProps={{SelectDisplayProps: {"aria-required": true}}} label={t("Категория товаров")} value={categoryId} disabled={importBusy || categories.isLoading || categories.isError}
                    onChange={event => setCategoryId(event.target.value)} helperText={t("Категория автоматически подставится во все распознанные карточки.")}>
                    <MenuItem value="" disabled>{t("Выберите категорию товаров")}</MenuItem>
                    {(categories.data ?? []).map(category => <MenuItem key={category.id} value={category.id}>{category.name}</MenuItem>)}
                </TextField>
                {categories.isError && <QueryError error={categories.error} onRetry={categories.refetch}/>}
                {categories.data?.length === 0 && <Alert severity="info">{t("Сначала создайте категорию товаров в каталоге.")}</Alert>}
                <Button component="label" variant="outlined" disabled={importBusy}
                    onDragOver={event => {event.preventDefault(); if (!importBusy) setDragging(true);}}
                    onDragLeave={() => setDragging(false)}
                    onDrop={event => {event.preventDefault(); if (!importBusy) selectFiles(Array.from(event.dataTransfer.files));}}
                    sx={{minHeight: 160, p: 3, borderStyle: "dashed", borderWidth: 2, borderRadius: 3, textTransform: "none", bgcolor: dragging ? "action.selected" : "action.hover"}}>
                    <Stack spacing={1} alignItems="center" sx={{textAlign: "center"}}>
                        <UploadFileOutlinedIcon fontSize="large"/>
                        <Typography fontWeight={700}>{t("Выберите или перетащите файлы")}</Typography>
                        <Typography variant="body2" color="text.secondary">{t("Excel, CSV, PDF или фото · до 10 МБ на файл. GTIN необязателен.")}</Typography>
                    </Stack>
                    <input type="file" multiple hidden disabled={importBusy} aria-label={t("Файлы для генерации")} accept=".xlsx,.xls,.csv,.pdf,.png,.jpg,.jpeg,.webp" onChange={event => {selectFiles(Array.from(event.target.files ?? [])); event.target.value = "";}}/>
                </Button>
                <Button component="label" variant="outlined" startIcon={<PhotoCameraOutlinedIcon/>} disabled={importBusy} sx={{alignSelf: "flex-start"}}>
                    {t("Сфотографировать список")}
                    <input type="file" hidden disabled={importBusy} aria-label={t("Фото списка товаров")} accept="image/jpeg,image/png,image/webp" capture="environment" onChange={event => {selectFiles(Array.from(event.target.files ?? [])); event.target.value = "";}}/>
                </Button>
                <Typography variant="body2" color="text.secondary">{t("В буфер попадут только товары с распознанным названием. Описание необязательно, неизвестная цена — 0.")}</Typography>
                {!!files.length && <Stack direction="row" gap={1} flexWrap="wrap">{files.map((file, index) => <Chip key={`${file.name}-${index}`} label={file.name} disabled={uploading} onDelete={() => setFiles(current => current.filter((_, position) => position !== index))} sx={{maxWidth: "100%"}}/>)}</Stack>}
                {aiRequired && <Alert severity="warning">{t("Для фото и PDF необходимо распознавание с ИИ. Подключите ИИ.")}</Alert>}
                <Button variant="contained" disabled={!files.length || !categoryId || importBusy || categories.isLoading || categories.isError || capabilities.isLoading || capabilities.isError || aiRequired} onClick={() => void upload()}>{t("Подготовить карточки")}</Button>
                {uploading && <><LinearProgress/><Typography variant="body2">{t("Распознавание файла")}: {progress}</Typography></>}
            </Stack></Surface>
            {error && <Alert severity="error" onClose={() => setError("")}>{error}</Alert>}
            <Surface><Stack spacing={2}>
                <Stack direction="row" gap={1} flexWrap="wrap" justifyContent="space-between" alignItems="center">
                    <Typography variant="h6">{t("Буфер одобрения")}</Typography>
                    <Button color="error" disabled={bufferBusy || batches.isFetching || !batches.data?.length} onClick={() => {setClearError(""); setClearOpen(true);}}>{t("Очистить весь буфер")}</Button>
                </Stack>
                {batches.isLoading && <LinearProgress/>}
                {batches.isError && <QueryError error={batches.error} onRetry={batches.refetch}/>}
                {batches.data && batches.data.length === 0 && <Typography color="text.secondary">{t("Загрузите первый файл, чтобы подготовить карточки.")}</Typography>}
                <Stack direction="row" gap={1} flexWrap="wrap">
                    {(batches.data ?? []).map(item => <Button key={item.id} variant={batchId === item.id ? "contained" : "outlined"} disabled={bufferBusy} onClick={() => setSearch({batch: item.id})}>
                        {item.fileName} · {t("На одобрении")}: {item.pending} · {t("В каталоге")}: {item.approved}
                    </Button>)}
                </Stack>
                {batch.isFetching && <LinearProgress/>}
                {batch.isError && <QueryError error={batch.error} onRetry={batch.refetch}/>}
                {activeBatch && <>
                    <Typography variant="h6" sx={{overflowWrap: "anywhere"}}>{activeBatch.fileName}</Typography>
                    <Typography>{t("Распознано товаров")}: {activeBatch.drafts.length}</Typography>
                    <Alert severity="info">Для нового товара, требующего регистрации, сначала подготовьте заявку ePASS и получите GTIN. Одобрение черновика сразу создаёт карточку в каталоге с остатком 0.</Alert>
                    <Button component={RouterLink} to={`/catalogGeneration/epass?batch=${encodeURIComponent(activeBatch.id)}`} variant="outlined"
                        disabled={bufferBusy || batch.isFetching || !activeBatch.drafts.some(item => item.status === "Pending")}>Подготовить заявку ePASS</Button>
                    <Stack direction="row" gap={1} flexWrap="wrap" alignItems="center">
                        <Typography variant="body2">{t("Выбрано карточек")}: {selected.length}</Typography>
                        <Button variant="contained" color="success" disabled={!selected.length || bufferBusy || batch.isFetching} onClick={() => void approveSelected()}>{t("Добавить выбранные в каталог")}</Button>
                    </Stack>
                    {approvingMany.isLoading && <LinearProgress/>}
                    {approvalResult?.batchId === batchId && <Alert severity={approvalResult.failed.length ? "warning" : "success"}>
                        {t("Добавлено в каталог")}: {approvalResult.approved.length}. {t("Не добавлено")}: {approvalResult.failed.length}.
                        {!!approvalResult.failed.length && <Box component="ul" sx={{m: 0, mt: 1, pl: 2}}>{approvalResult.failed.map(item => <li key={item.id}>{activeBatch.drafts.find(draft => draft.id === item.id)?.card.name}: {item.error}</li>)}</Box>}
                    </Alert>}
                    <TableContainer component={Box}><Table size="small" aria-label={t("Буфер одобрения")}>
                        <TableHead><TableRow><TableCell padding="checkbox"><Checkbox inputProps={{"aria-label": t("Выделить все распознанные карточки")}}
                            checked={eligible.length > 0 && selected.length === eligible.length} indeterminate={selected.length > 0 && selected.length < eligible.length}
                            disabled={!eligible.length || bufferBusy || batch.isFetching} onChange={(_, checked) => setSelectedIds(checked ? eligible.map(item => item.id) : [])}/></TableCell>
                            <TableCell>{t("Name")}</TableCell><TableCell>GTIN</TableCell><TableCell>{t("Price")}</TableCell><TableCell>{t("Status")}</TableCell><TableCell/></TableRow></TableHead>
                        <TableBody>{activeBatch.drafts.map(item => <TableRow key={item.id}>
                            <TableCell padding="checkbox">{item.status === "Pending" && !!item.card.name.trim() && <Checkbox inputProps={{"aria-label": `${t("Выбрать карточку")}: ${item.card.name}`}}
                                checked={selectedIds.includes(item.id)} disabled={bufferBusy || batch.isFetching}
                                onChange={(_, checked) => setSelectedIds(current => checked ? [...current, item.id] : current.filter(id => id !== item.id))}/>}</TableCell>
                            <TableCell sx={{maxWidth: 320, overflowWrap: "anywhere"}}>{item.card.name || t("Без названия")}</TableCell>
                            <TableCell>{item.card.gtin || "—"}</TableCell><TableCell>{item.card.price ?? 0}</TableCell>
                            <TableCell><Chip size="small" label={statusLabel[item.status]} color={item.status === "Approved" ? "success" : item.status === "Rejected" ? "default" : "warning"}/></TableCell>
                            <TableCell><Stack direction="row" gap={1} flexWrap="wrap">
                                <Button disabled={bufferBusy || batch.isFetching} onClick={() => setDraftId(item.id)}>{t("Просмотреть")}</Button>
                                <Button color="error" disabled={bufferBusy || batch.isFetching} aria-label={`${t("Удалить карточку")}: ${item.card.name || t("Без названия")}`}
                                    onClick={() => {setDeleteError(""); setDeleteTarget(item);}}>{t("Удалить")}</Button>
                            </Stack></TableCell>
                        </TableRow>)}</TableBody>
                    </Table></TableContainer>
                </>}
            </Stack></Surface>
            {draftId && draft.isFetching && <LinearProgress/>}
            {draftId && draft.isError && <QueryError error={draft.error} onRetry={draft.refetch}/>}
            {draftId && draft.currentData && <ProductDraftEditor key={draft.currentData.id} draft={draft.currentData} categories={categories.data ?? []} onClose={() => setDraftId("")}/>}
        </Stack>
        <Dialog open={clearOpen} onClose={() => {if (!clearing.isLoading) setClearOpen(false);}} aria-labelledby="clear-recognition-title" aria-describedby="clear-recognition-description">
            <DialogTitle id="clear-recognition-title">{t("Очистить весь буфер")}</DialogTitle>
            <DialogContent>
                <DialogContentText id="clear-recognition-description">{t("Все загрузки, исходные файлы и карточки текущей компании будут удалены из буфера. Товары, уже добавленные в каталог, сохранятся. Отменить очистку нельзя.")}</DialogContentText>
                {clearError && <Alert severity="error" sx={{mt: 2}}>{clearError}</Alert>}
            </DialogContent>
            <DialogActions>
                <Button disabled={clearing.isLoading} onClick={() => setClearOpen(false)}>{t("Отмена")}</Button>
                <Button color="error" variant="contained" disabled={clearing.isLoading} onClick={() => void clear()}>{t("Очистить")}</Button>
            </DialogActions>
        </Dialog>
        <Dialog open={deleteTarget !== null} onClose={() => {if (!deleting.isLoading) setDeleteTarget(null);}} aria-labelledby="delete-recognition-draft-title" aria-describedby="delete-recognition-draft-description">
            <DialogTitle id="delete-recognition-draft-title">{t("Удалить карточку")}</DialogTitle>
            <DialogContent>
                <Typography sx={{mb: 2, overflowWrap: "anywhere"}}>{deleteTarget?.card.name || t("Без названия")}</Typography>
                <DialogContentText id="delete-recognition-draft-description">{t("Карточка будет удалена из буфера. Исходный файл и товары, уже добавленные в каталог, сохранятся. Отменить удаление нельзя.")}</DialogContentText>
                {deleteError && <Alert severity="error" sx={{mt: 2}}>{deleteError}</Alert>}
            </DialogContent>
            <DialogActions>
                <Button disabled={deleting.isLoading} onClick={() => setDeleteTarget(null)}>{t("Отмена")}</Button>
                <Button color="error" variant="contained" disabled={deleting.isLoading} onClick={() => void removeCard()}>{t("Удалить")}</Button>
            </DialogActions>
        </Dialog>
    </MainDiv>;
}
