import React from "react";
import {Alert, Button} from "@mui/material";
import {getApiErrorMessage} from "../../api/errors";
import {useTranslation} from "../../i18n";

export default function QueryError({error, onRetry}: {error?: unknown; onRetry: () => unknown}) {
    const {t} = useTranslation();
    return <Alert severity="error" action={<Button onClick={() => void onRetry()}>{t("Повторить")}</Button>}>
        {getApiErrorMessage(error, t("Не удалось загрузить данные. Повторите запрос."))}
    </Alert>;
}
