import React, {ChangeEvent, useEffect, useId, useState} from "react";
import {Button} from "@mui/material";
import ImageOutlinedIcon from "@mui/icons-material/ImageOutlined";
import UploadFileOutlinedIcon from "@mui/icons-material/UploadFileOutlined";
import styledCom from "styled-components";

interface ImageUploadFieldProps {
    label: string;
    actionText: string;
    emptyText: string;
    hint?: string;
    fileName?: string;
    previewSrc?: string;
    previewAlt: string;
    accept?: string;
    disabled?: boolean;
    onChange: (event: ChangeEvent<HTMLInputElement>) => void;
}

const Field = styledCom.div({
    display: "grid",
    gap: "8px",
    width: "100%",
    minWidth: 0,
});

const FieldLabel = styledCom.label({
    width: "fit-content",
    color: "var(--color-muted)",
    fontSize: "13px",
    fontWeight: 650,
    lineHeight: 1.4,
});

const UploadCard = styledCom.div({
    display: "grid",
    gridTemplateColumns: "88px minmax(0, 1fr)",
    gap: "14px",
    alignItems: "center",
    minWidth: 0,
    padding: "12px",
    border: "1px solid var(--color-border)",
    borderRadius: "12px",
    background: "var(--color-surface-muted)",

    "@media (max-width: 420px)": {
        gridTemplateColumns: "72px minmax(0, 1fr)",
        gap: "10px",
        padding: "10px",
    },
});

const Preview = styledCom.div({
    display: "grid",
    placeItems: "center",
    width: "88px",
    height: "88px",
    overflow: "hidden",
    color: "var(--color-muted)",
    border: "1px solid var(--color-border)",
    borderRadius: "10px",
    background: "var(--color-surface)",

    img: {
        width: "100%",
        height: "100%",
        objectFit: "cover",
    },

    "@media (max-width: 420px)": {
        width: "72px",
        height: "72px",
    },
});

const FileDetails = styledCom.div({
    display: "grid",
    gap: "7px",
    minWidth: 0,
});

const FileName = styledCom.span({
    minWidth: 0,
    color: "var(--color-text)",
    fontSize: "13px",
    fontWeight: 620,
    lineHeight: 1.4,
    overflowWrap: "anywhere",
});

const Hint = styledCom.span({
    color: "var(--color-muted)",
    fontSize: "12px",
    lineHeight: 1.4,
});

const VisuallyHiddenInput = styledCom.input({
    position: "absolute",
    width: "1px",
    height: "1px",
    padding: 0,
    margin: "-1px",
    overflow: "hidden",
    clip: "rect(0 0 0 0)",
    whiteSpace: "nowrap",
    border: 0,
});

const ImageUploadField = ({
    label,
    actionText,
    emptyText,
    hint,
    fileName,
    previewSrc,
    previewAlt,
    accept = "image/png,image/jpeg,image/webp",
    disabled = false,
    onChange,
}: ImageUploadFieldProps) => {
    const inputId = useId();
    const hintId = useId();
    const [previewFailed, setPreviewFailed] = useState(false);

    useEffect(() => {
        setPreviewFailed(false);
    }, [previewSrc]);

    const hasPreview = Boolean(previewSrc) && !previewFailed;

    return (
        <Field>
            <FieldLabel htmlFor={inputId}>{label}</FieldLabel>
            <UploadCard>
                <Preview aria-hidden={!hasPreview}>
                    {hasPreview ? (
                        <img
                            src={previewSrc}
                            alt={previewAlt}
                            onError={() => setPreviewFailed(true)}
                        />
                    ) : (
                        <ImageOutlinedIcon fontSize="large" aria-hidden="true"/>
                    )}
                </Preview>
                <FileDetails>
                    <Button
                        component="label"
                        variant="outlined"
                        startIcon={<UploadFileOutlinedIcon/>}
                        disabled={disabled}
                        fullWidth
                    >
                        {actionText}
                        <VisuallyHiddenInput
                            id={inputId}
                            type="file"
                            accept={accept}
                            aria-describedby={hint ? hintId : undefined}
                            onChange={onChange}
                            disabled={disabled}
                        />
                    </Button>
                    <FileName>{fileName || emptyText}</FileName>
                    {hint && <Hint id={hintId}>{hint}</Hint>}
                </FileDetails>
            </UploadCard>
        </Field>
    );
};

export default ImageUploadField;
