import React, {useEffect, useState} from "react";
import {Alert, Button, Dialog, DialogActions, DialogContent, DialogTitle, MenuItem, Stack, TextField, Typography} from "@mui/material";
import {Link as RouterLink} from "react-router-dom";
import {ProductRecognitionDraft} from "../../../models/productRecognition";
import {ICategory} from "../../../models/category";
import {useTranslation} from "../../../i18n";
import {getApiErrorMessage} from "../../../api/errors";
import {useApproveRecognitionDraftMutation, useRejectRecognitionDraftMutation, useSaveRecognitionDraftMutation} from "../../products/productsApi";
import CustomFieldEditor, {customFieldsToRows, customFieldRowsToRecord, getCustomFieldsValidationError} from "../../shared/customFields/CustomFieldEditor";
import CharacteristicEditor from "../../shared/characteristics/CharacteristicEditor";
import ImageUploadField from "../../../ui/fileUpload/ImageUploadField";

interface Props { draft: ProductRecognitionDraft; categories: ICategory[]; onClose: () => void; }

export default function ProductDraftEditor({draft, categories, onClose}: Props) {
    const {t} = useTranslation();
    const [card, setCard] = useState({...draft.card});
    const [fields, setFields] = useState(customFieldsToRows(draft.card.fields));
    const [image, setImage] = useState<File | null>(null);
    const [removeImage, setRemoveImage] = useState(false);
    const [imagePreview, setImagePreview] = useState<string>();
    const [error, setError] = useState("");
    const [conflicted, setConflicted] = useState(false);
    const [dirty, setDirty] = useState(false);
    const [version, setVersion] = useState(draft.version);
    const [save, saving] = useSaveRecognitionDraftMutation();
    const [approve, approving] = useApproveRecognitionDraftMutation();
    const [reject, rejecting] = useRejectRecognitionDraftMutation();
    const busy = saving.isLoading || approving.isLoading || rejecting.isLoading;
    const pending = draft.status === "Pending";
    useEffect(() => {
        if (!image) {setImagePreview(undefined); return;}
        const url = URL.createObjectURL(image);
        setImagePreview(url);
        return () => URL.revokeObjectURL(url);
    }, [image]);
    const change = (patch: Partial<typeof card>) => {setCard(value => ({...value, ...patch})); setDirty(true);};
    const close = () => {if (!busy && (!dirty || window.confirm(t("Закрыть без сохранения изменений?")))) onClose();};
    const reloadCard = () => {
        if (dirty && !window.confirm(t("Загрузить актуальную карточку и отменить несохранённые изменения?"))) return;
        setCard({...draft.card});
        setFields(customFieldsToRows(draft.card.fields));
        setImage(null);
        setRemoveImage(false);
        setVersion(draft.version);
        setDirty(false);
        setConflicted(false);
        setError("");
    };

    const submit = async (publish: boolean) => {
        setError("");
        const fieldError = getCustomFieldsValidationError(fields, t);
        if (fieldError) {setError(fieldError); return;}
        if (publish) {
            if (!card.name.trim()) {setError(t("Перед одобрением заполните название товара.")); return;}
            if (!card.categoryId) {setError(t("Выберите категорию товаров.")); return;}
            if (card.price !== null && (!Number.isFinite(card.price) || card.price < 0)) {setError(t("Цена не может быть отрицательной.")); return;}
            if (card.gtin && !/^(?:\d{8}|\d{12}|\d{13}|\d{14})$/.test(card.gtin)) {setError(t("GTIN must contain 8, 12, 13, or 14 digits.")); return;}
            const characteristicError = getCustomFieldsValidationError(card.characteristics, t);
            if (characteristicError) {setError(characteristicError); return;}
        }
        if (image && image.size > 5 * 1024 * 1024) {setError(t("Изображение должно быть не больше 5 МБ.")); return;}
        const body = new FormData();
        body.append("version", version);
        body.append("cardJson", JSON.stringify({...card, description: card.description?.trim() || null, price: card.price ?? 0, fields: customFieldRowsToRecord(fields)}));
        body.append("removeImage", String(removeImage));
        if (image) body.append("imageFile", image);
        let savedSuccessfully = false;
        try {
            const saved = await save({id: draft.id, body}).unwrap();
            savedSuccessfully = true;
            setVersion(saved.version);
            setDirty(false);
            setConflicted(false);
            if (publish) await approve({id: draft.id, version: saved.version}).unwrap();
            onClose();
        } catch (failure) {
            if (!savedSuccessfully && failure && typeof failure === "object" && "status" in failure && failure.status === 409) setConflicted(true);
            setError(getApiErrorMessage(failure, t("Не удалось сохранить карточку.")));
        }
    };

    const rejectCard = async () => {
        try {await reject({id: draft.id, version}).unwrap(); onClose();}
        catch (failure) {
            if (failure && typeof failure === "object" && "status" in failure && failure.status === 409) setConflicted(true);
            setError(getApiErrorMessage(failure, t("Не удалось отклонить карточку.")));
        }
    };

    return <Dialog open onClose={close} maxWidth="md" fullWidth aria-labelledby="draft-title">
        <DialogTitle id="draft-title">{t("Черновик товара")} #{draft.position}</DialogTitle>
        <DialogContent dividers>
            <Stack spacing={2}>
                {error && <Alert severity="error">{error}</Alert>}
                {conflicted && draft.version !== version && <Button disabled={busy} onClick={reloadCard}>{t("Загрузить актуальную карточку")}</Button>}
                {draft.warnings.map((warning, index) => <Alert key={index} severity="warning">{warning}</Alert>)}
                {pending && !card.gtin.trim() && <Alert severity="info">Если товар требует регистрации в ePASS, сохраните черновик и подготовьте заявку из буфера. Добавление в каталог само по себе не присваивает GTIN.</Alert>}
                {pending && <Typography variant="body2" color="text.secondary">{t("Проверьте распознанные сведения. После одобрения карточка появится в каталоге.")}</Typography>}
                <fieldset disabled={!pending || busy} style={{border: 0, padding: 0, margin: 0, minWidth: 0}}>
                    <Stack spacing={2}>
                        <TextField select disabled={!pending || busy} label={t("Category")} value={card.categoryId ?? ""} onChange={event => change({categoryId: event.target.value ? Number(event.target.value) : null})}>
                            <MenuItem value="">{t("Не выбрана")}</MenuItem>
                            {categories.map(category => <MenuItem key={category.id} value={category.id}>{category.name}</MenuItem>)}
                        </TextField>
                        <TextField label={t("Name")} required value={card.name} onChange={event => change({name: event.target.value})}/>
                        <TextField label="GTIN" helperText={t("Необязательно")} value={card.gtin} onChange={event => change({gtin: event.target.value})}/>
                        <TextField label={t("Description")} helperText={t("Необязательно")} multiline minRows={3} value={card.description ?? ""} onChange={event => change({description: event.target.value})}/>
                        <TextField label={t("Price")} helperText={t("Если цена не распознана, используется 0.")} type="number" inputProps={{min: 0, max: 1000000000000, step: "any"}} value={card.price ?? 0} onChange={event => change({price: event.target.value === "" ? null : Number(event.target.value)})}/>
                        <ImageUploadField label={t("Image")} actionText={t("Choose file")} emptyText={t("No file selected")} hint={t("PNG, JPG or WEBP")} fileName={image?.name}
                            previewSrc={removeImage ? undefined : imagePreview ?? draft.imageDataUrl ?? undefined} previewAlt={card.name}
                            disabled={!pending || busy} onChange={event => {setImage(event.target.files?.[0] ?? null); setRemoveImage(false); setDirty(true);}}/>
                        {(draft.hasImage || image) && <Button onClick={() => {setImage(null); setRemoveImage(true); setDirty(true);}}>{t("Удалить изображение")}</Button>}
                        <CustomFieldEditor value={fields} onChange={value => {setFields(value); setDirty(true);}}/>
                        <CharacteristicEditor title={t("Characteristics")} nameLabel={t("Characteristic name")} valueLabel={t("Value")}
                            addLabel={t("Add characteristic")} removeLabel={t("Remove characteristic")} value={card.characteristics} onChange={value => change({characteristics: value})}/>
                    </Stack>
                </fieldset>
                {draft.rawText && <details><summary>{t("Исходные сведения")}</summary><Typography component="pre" variant="body2" sx={{whiteSpace: "pre-wrap", overflowWrap: "anywhere", maxHeight: 280, overflow: "auto"}}>{draft.rawText}</Typography></details>}
            </Stack>
        </DialogContent>
        <DialogActions sx={{flexWrap: "wrap", gap: 1}}>
            <Button disabled={busy} onClick={close}>{t("Close")}</Button>
            {pending ? <>
                <Button color="error" disabled={busy} onClick={() => void rejectCard()}>{t("Отклонить")}</Button>
                <Button disabled={busy} onClick={() => void submit(false)}>{t("Сохранить черновик")}</Button>
                <Button variant="contained" color="success" disabled={busy} onClick={() => void submit(true)}>{t("Одобрить и добавить в каталог")}</Button>
            </> : draft.productId && <Button component={RouterLink} to={`/productDetails/${draft.productId}`}>{t("Открыть товар")}</Button>}
        </DialogActions>
    </Dialog>;
}
